def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    opp_budgets = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            opp_budgets.append(opp.get('budget', 0))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive_opponents:
        return max(0, min(budget, DAILY_SALARY * 0.35))

    highest_prev = max(prev_bids) if prev_bids else DAILY_SALARY * 0.8
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else DAILY_SALARY * 0.8
    richest_opp = max(opp_budgets) if opp_budgets else 0

    units_today = int(supply // WATER_REQ)
    scarce = units_today <= 1
    high_supply = supply >= 24

    critical = hp <= 2 or no_water_days >= 2
    semi_critical = hp <= 4 or no_water_days >= 1

    if critical:
        target = highest_prev + 2.5
        if richest_opp < target:
            target = max(target, richest_opp + 1)
        return max(0, min(budget, target))

    if high_supply and semi_critical:
        target = max(DAILY_SALARY * 0.9, avg_prev + 1.5)
        return max(0, min(budget, target))

    if scarce:
        if hp >= 6 and no_water_days == 0:
            return max(0, min(budget, DAILY_SALARY * 0.08))
        if semi_critical:
            target = max(DAILY_SALARY * 0.88, highest_prev + 1.0)
            return max(0, min(budget, target))
        return max(0, min(budget, DAILY_SALARY * 0.12))

    if hp >= 7 and budget < DAILY_SALARY * 4:
        return max(0, min(budget, DAILY_SALARY * 0.18))

    if semi_critical:
        target = max(DAILY_SALARY * 0.72, avg_prev * 0.92)
        return max(0, min(budget, target))

    if day >= 8:
        return max(0, min(budget, DAILY_SALARY * 0.45))

    return max(0, min(budget, DAILY_SALARY * 0.2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents, just secure enough water cheaply.
    if not alive_opps:
        target = 0.35 * DAILY_SALARY
        return max(0.0, min(float(my_status.get('budget', 0.0)), target))

    # Read yesterday bids from each opponent (immediate reaction only)
    prev_bids = []
    prev_hp_after = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid', 0.0)))
            except Exception:
                pass
            if prev.get('hp_after') is not None:
                try:
                    prev_hp_after.append(float(prev.get('hp_after')))
                except Exception:
                    pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Supply pressure: lower supply implies higher chance we need to win more.
    # With req=9 and supply in [15,25], the effective share is tight.
    # Use a normalized pressure in [0,1].
    pressure = 0.0
    if MAX_SUPPLY - MIN_SUPPLY > 0:
        pressure = (float(supply) - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)
    # pressure=0 at MIN_SUPPLY (worst), pressure=1 at MAX_SUPPLY (best)
    supply_need = 1.0 - pressure

    # Baseline bid: moderate, scaled by supply_need and our HP.
    # If we're low HP, bid more to avoid running out of water days.
    hp_need = 0.0
    if my_hp <= 1.0:
        hp_need = 1.0
    elif my_hp <= 3.0:
        hp_need = 0.7
    elif my_hp <= 5.0:
        hp_need = 0.35
    else:
        hp_need = 0.15

    # Opponent aggression signal: Cindy survived with high bids; high average/highest suggests bidding war.
    # If highest_prev_bid is high, we may need to outbid slightly; otherwise stay cheaper.
    aggression = 0.0
    if highest_prev_bid >= 0.85 * DAILY_SALARY:
        aggression = 1.0
    elif avg_prev_bid >= 0.7 * DAILY_SALARY:
        aggression = 0.7
    elif avg_prev_bid >= 0.5 * DAILY_SALARY:
        aggression = 0.4
    else:
        aggression = 0.2

    # Compute a target bid.
    # Keep within budget; also avoid overpaying when HP is comfortable and supply is higher.
    base = 0.45 * DAILY_SALARY
    target = base * (0.6 + 0.8 * supply_need) * (0.7 + 0.6 * hp_need)

    # If yesterday showed very high bids, bid up but only to a capped level.
    if aggression >= 0.9:
        target = max(target, min(my_budget, 0.75 * DAILY_SALARY))
        # Slightly above highest yesterday to steal water if feasible.
        target = max(target, min(my_budget, highest_prev_bid + 2.5))
    elif aggression >= 0.6:
        target = max(target, min(my_budget, 0.6 * DAILY_SALARY))
        target = max(target, min(my_budget, highest_prev_bid * 0.95))
    else:
        # When not aggressive, stay near baseline but still responsive to supply.
        target = min(my_budget, target)

    # Hard caps for risk control.
    # If HP is very low, allow higher spending; otherwise cap at ~0.75 salary.
    if my_hp <= 2.0:
        cap = 0.95 * DAILY_SALARY
    else:
        cap = 0.75 * DAILY_SALARY

    target = min(float(my_budget), float(cap), float(target))
    if target < 0.0:
        target = 0.0

    # Ensure we always bid at least a small amount if budget allows.
    if my_budget > 0 and target == 0.0:
        target = min(my_budget, 0.1 * DAILY_SALARY)

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return min(my_status['budget'], 1.0)

    bid = DAILY_SALARY * 0.5

    if my_status['hp'] <= 2:
        bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 5:
        bid = DAILY_SALARY * 0.8
    elif my_status['no_water_days'] > 0:
        bid = DAILY_SALARY * 0.7

    estimated_total_water_needed = WATER_REQ + sum([o['water_requirement'] for o in alive_opponents])

    if day_context['supply'] < estimated_total_water_needed:
        bid = max(bid, DAILY_SALARY * 0.75)

    if day_context['supply'] < WATER_REQ * 1.5:
        bid = max(bid, DAILY_SALARY * 0.85)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)
        if max_yesterday_bid >= DAILY_SALARY * 0.7:
            bid = max(bid, max_yesterday_bid + 5)
        elif max_yesterday_bid > bid:
            bid = max(bid, max_yesterday_bid + 1)

    remaining_days = EPISODE_DAYS - int(day_context['day'])
    if remaining_days <= 3 and my_status['hp'] < 10:
        bid = max(bid, DAILY_SALARY * 0.9)
    if remaining_days <= 1 and my_status['hp'] <= 2:
        bid = DAILY_SALARY * 0.99

    bid = max(1.0, bid)

    final_bid = min(bid, my_status['budget'])
    final_bid = max(0.0, final_bid)

    return final_bid
